const out = [];
for (const it of items) {
  for (const p of (it.json.projects || [])) {
    out.push({ json: { project_id: p.project_id, project_name: p.name } });
  }
}
return out;

const reqs = $('Flatten Projects').all();
const res = $input.all();
const NUM = /^[0-9]+$/;
const TARGET = 'z_human';
const inv = {};
const snap = [];
const perProject = {};
const failed = [];
let totalKeys = 0;
let unpaired = 0;

for (let i = 0; i < res.length; i++) {
  const pi = res[i].pairedItem;
  let idx = i;
  if (pi && typeof pi === 'object' && typeof pi.item === 'number') { idx = pi.item; }
  else if (typeof pi === 'number') { idx = pi; }
  else { unpaired++; }
  const metaItem = reqs[idx] || reqs[i];
  if (!metaItem) { continue; }
  const meta = metaItem.json;
  const r = res[i].json || {};
  if (r.statusCode !== 200) { failed.push(meta.project_name + ' (status ' + r.statusCode + ')'); continue; }
  if (!perProject[meta.project_name]) { perProject[meta.project_name] = { project_id: meta.project_id, keys_seen: 0, z_human: 0, numeric_keys: 0, numeric_tags: {} }; }
  const pp = perProject[meta.project_name];
  const keys = (r.body && r.body.keys) ? r.body.keys : [];
  for (const k of keys) {
    totalKeys++;
    pp.keys_seen++;
    const tags = k.tags || [];
    let hasZ = false;
    const numHits = [];
    for (const t of tags) {
      if (!inv[t]) { inv[t] = { keys: 0, projects: {} }; }
      inv[t].keys++;
      inv[t].projects[meta.project_name] = (inv[t].projects[meta.project_name] || 0) + 1;
      if (t === TARGET) { hasZ = true; }
      else if (NUM.test(t)) { numHits.push(t); }
    }
    if (hasZ) { pp.z_human++; }
    if (numHits.length > 0) {
      pp.numeric_keys++;
      for (const t of numHits) { pp.numeric_tags[t] = (pp.numeric_tags[t] || 0) + 1; }
    }
    if (hasZ || numHits.length > 0) {
      const after = [];
      for (const t of tags) { if (t !== TARGET && !NUM.test(t)) { after.push(t); } }
      const removed = [];
      if (hasZ) { removed.push(TARGET); }
      for (const t of numHits) { removed.push(t); }
      snap.push({ project_id: meta.project_id, project_name: meta.project_name, key_id: k.key_id, is_archived: !!k.is_archived, tags_before: tags, tags_after: after, removed: removed });
    }
  }
}

const numericTags = {};
const mixedTags = [];
for (const t in inv) {
  if (NUM.test(t)) { numericTags[t] = inv[t]; }
  else if (/[0-9]/.test(t)) { mixedTags.push(t); }
}

return [
  { json: { kind: 'summary', total_keys: totalKeys, projects_scanned: Object.keys(perProject).length, distinct_tags: Object.keys(inv).length, unpaired_pages: unpaired, z_human_inventory: inv[TARGET] || null, numeric_tags: numericTags, mixed_digit_tags_kept: mixedTags, affected_keys: snap.length, per_project: perProject, failed: failed } },
  { json: { kind: 'snapshot', rows: snap } }
];
